const C = {
  bg: "#0F1216", panel: "#1A1F26", panelAlt: "#20262E", border: "#2A313B",
  text: "#EDEFF2", sub: "#8B94A1", over: "#E4A93B", under: "#4E8FD6",
  neutral: "#5B6472", danger: "#D9756B", rookie: "#7BC67E",
};

const STAT_TYPES = {
  QB: [{ key: "pass_yards", label: "Pass Yards" }, { key: "rush_yards", label: "Rush Yards" }],
  RB: [{ key: "rush_yards", label: "Rush Yards" }, { key: "rec_yards", label: "Rec Yards" }, { key: "receptions", label: "Receptions" }],
  WR: [{ key: "rec_yards", label: "Rec Yards" }, { key: "receptions", label: "Receptions" }],
  TE: [{ key: "rec_yards", label: "Rec Yards" }, { key: "receptions", label: "Receptions" }],
};
const POSITIONS = ["QB", "RB", "WR", "TE"];

function leanFromLine(stat, line) {
  if (!stat || !line || isNaN(parseFloat(line))) return { lean: "—", confidence: null, edge: null };
  const l = parseFloat(line);
  const edge = stat.projection - l;
  const edgePct = l !== 0 ? edge / l : 0;
  if (Math.abs(edgePct) < 0.04) return { lean: "PASS", confidence: "Low", edge };
  const lean = edge > 0 ? "OVER" : "UNDER";
  const confidence = Math.abs(edgePct) > 0.18 ? "High" : Math.abs(edgePct) > 0.09 ? "Medium" : "Low";
  return { lean, confidence, edge };
}

function LeanBadge({ lean, confidence }) {
  const color = lean === "OVER" ? C.over : lean === "UNDER" ? C.under : C.neutral;
  return (
    <div style={{ display: "inline-flex", alignItems: "center", gap: 5, padding: "3px 9px", borderRadius: 6, background: color + "22", border: `1px solid ${color}55`, color, fontWeight: 700, fontSize: 12.5 }}>
      {lean === "OVER" && <TrendingUp size={13} />}
      {lean === "UNDER" && <TrendingDown size={13} />}
      {(lean === "PASS" || lean === "—") && <Minus size={13} />}
      {lean}{confidence ? ` · ${confidence}` : ""}
    </div>
  );
}

function InjuryTag({ status }) {
  if (!status) return null;
  const isOut = /out|ir|doubtful/i.test(status);
  return (
    <div style={{ display: "inline-flex", alignItems: "center", gap: 4, fontSize: 11, color: isOut ? C.danger : "#D9B34A", marginTop: 4 }}>
      <AlertTriangle size={11} /> {status}
    </div>
  );
}

function RookieTag() {
  return (
    <div style={{ display: "inline-flex", alignItems: "center", gap: 4, fontSize: 10.5, color: C.rookie, marginTop: 4, fontWeight: 600 }}>
      <Sprout size={11} /> Limited history · low confidence
    </div>
  );
}

function DecliningFormTag() {
  return (
    <div style={{ display: "inline-flex", alignItems: "center", gap: 4, fontSize: 10.5, color: "#D9B34A", marginTop: 4, fontWeight: 600 }}>
      <TrendingDown size={11} /> Declining form · projection pulled toward recent games
    </div>
  );
}

function PlayerRow({ player, statKey, active, onSelect, line }) {
  const stat = player.stats[statKey];
  const { lean, confidence } = leanFromLine(stat, line);
  return (
    <div onClick={() => onSelect(player.name)} style={{
      background: active ? C.panelAlt : "transparent",
      border: `1px solid ${active ? C.over + "55" : "transparent"}`,
      borderRadius: 8, padding: "10px 12px", cursor: "pointer",
      display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8,
      opacity: stat ? 1 : 0.4,
    }}>
      <div style={{ minWidth: 0 }}>
        <div style={{ fontWeight: 700, fontSize: 13.5, color: C.text, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
          {player.name}
        </div>
        <div style={{ fontSize: 11, color: C.sub }}>
          {player.team} vs {player.week2Opp || "TBD"} {stat ? `· proj ${stat.projection}` : "· no data"}
        </div>
        {player.isLowConfidence && <RookieTag />}
        <InjuryTag status={player.injuryStatus} />
      </div>
      {stat && <LeanBadge lean={lean} confidence={confidence} />}
    </div>
  );
}

function DetailPanel({ player, statKey, statLabel, line, setLine }) {
  if (!player) {
    return <div style={{ display: "flex", alignItems: "center", justifyContent: "center", height: "100%", color: C.sub, fontSize: 14 }}>Select a player to see the full breakdown.</div>;
  }
  const stat = player.stats[statKey];
  if (!stat || stat.projection === null) {
    return (
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", height: "100%", color: C.sub, fontSize: 14, textAlign: "center", padding: 20 }}>
        No {statLabel.toLowerCase()} data available for {player.name} yet.
      </div>
    );
  }
  const { lean, confidence, edge } = leanFromLine(stat, line);

  const StatBox = ({ label, value, sub }) => (
    <div style={{ background: C.panelAlt, border: `1px solid ${C.border}`, borderRadius: 8, padding: "10px 12px", flex: 1, minWidth: 110 }}>
      <div style={{ fontSize: 11, color: C.sub, marginBottom: 4 }}>{label}</div>
      <div style={{ fontSize: 18, fontWeight: 700, color: C.text }}>{value}</div>
      {sub && <div style={{ fontSize: 10.5, color: C.sub, marginTop: 2 }}>{sub}</div>}
    </div>
  );

  const chartData = [
    { label: "Career avg (this team)", value: stat.priorAvg ?? 0, fill: C.neutral },
    { label: "Last 5 avg", value: stat.priorLast5 ?? 0, fill: C.neutral },
    { label: "Model projection", value: stat.projection, fill: player.isLowConfidence ? C.rookie : C.over },
  ];

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", flexWrap: "wrap", gap: 10 }}>
        <div>
          <div style={{ fontSize: 21, fontWeight: 800, color: C.text }}>{player.name}</div>
          <div style={{ fontSize: 13, color: C.sub }}>{player.team} · Week 2 vs {player.week2Opp || "TBD"} {stat.isHome ? "(home)" : "(away)"} · {statLabel}</div>
          {player.isLowConfidence && <RookieTag />}
          <InjuryTag status={player.injuryStatus} />
        </div>
        <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 6 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <span style={{ fontSize: 12, color: C.sub }}>Line</span>
            <input value={line} onChange={(e) => setLine(e.target.value)} placeholder="e.g. 64.5"
              style={{ width: 80, background: C.panelAlt, border: `1px solid ${C.border}`, borderRadius: 6, padding: "5px 8px", color: C.text, fontSize: 13 }} />
          </div>
          <LeanBadge lean={lean} confidence={player.isLowConfidence ? "Low" : confidence} />
        </div>
      </div>

      <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
        <StatBox label="Model projection" value={stat.projection} />
        <StatBox label="Career avg (this team)" value={stat.priorAvg ?? "—"} sub={stat.nPriorGames ? `${stat.nPriorGames} games on record` : undefined} />
        <StatBox label="Last 5 avg" value={stat.priorLast5 ?? "—"} />
        <StatBox label="Matchup factor" value={stat.matchupFactor ? `${stat.matchupFactor}x` : "—"} sub={stat.matchupFactor > 1.05 ? "easier matchup" : stat.matchupFactor < 0.95 ? "tougher matchup" : "average matchup"} />
        {line && !isNaN(parseFloat(line)) && <StatBox label="Edge vs line" value={`${edge >= 0 ? "+" : ""}${edge.toFixed(1)}`} />}
      </div>

      <div style={{ background: C.panel, border: `1px solid ${C.border}`, borderRadius: 10, padding: 16, height: 240 }}>
        <ResponsiveContainer width="100%" height="100%">
          <ComposedChart data={chartData} margin={{ top: 10, right: 10, left: -10, bottom: 0 }}>
            <CartesianGrid stroke={C.border} vertical={false} />
            <XAxis dataKey="label" stroke={C.sub} tick={{ fontSize: 10.5 }} interval={0} />
            <YAxis stroke={C.sub} tick={{ fontSize: 11 }} />
            <Tooltip contentStyle={{ background: C.panelAlt, border: `1px solid ${C.border}`, borderRadius: 6, fontSize: 12 }} labelStyle={{ color: C.text }} />
            {line && !isNaN(parseFloat(line)) && <ReferenceLine y={parseFloat(line)} stroke={C.text} strokeDasharray="4 4" label={{ value: "Line", fill: C.sub, fontSize: 11, position: "right" }} />}
            <Bar dataKey="value" radius={[4, 4, 0, 0]}>
              {chartData.map((d, i) => <Cell key={i} fill={d.fill} />)}
            </Bar>
          </ComposedChart>
        </ResponsiveContainer>
      </div>

      {stat.week1Actual !== null && stat.week1Actual !== undefined && (
        <div style={{ fontSize: 12, color: C.sub }}>Week 1 actual: {stat.week1Actual} {statLabel.toLowerCase()}</div>
      )}
      <div style={{ fontSize: 11.5, color: C.sub, lineHeight: 1.6, borderTop: `1px solid ${C.border}`, paddingTop: 12 }}>
        {player.isLowConfidence
          ? "Not enough games on this player's current team yet — projection is based on very limited data and should be treated as low-confidence."
          : "Model: a regression fit on thousands of historical player-games, using the specific blend of recent-form, home/away, team performance, and opponent-matchup variables that tested best for this position and stat in cross-validated backtesting."}
        {" "}This is a trend and matchup summary for content research, not betting advice.
      </div>
    </div>
  );
}

export default function PropDashboard() {
  const [position, setPosition] = useState("WR");
  const [statKey, setStatKey] = useState(STAT_TYPES.WR[0].key);
  const [selected, setSelected] = useState(null);
  const [search, setSearch] = useState("");
  const [lines, setLines] = useState({});

  const players = PLAYER_DATA[position];
  const filtered = useMemo(() => players.filter((p) => p.name.toLowerCase().includes(search.toLowerCase())), [players, search]);
  const activePlayer = players.find((p) => p.name === selected) || null;
  const lineKey = `${position}:${statKey}:${selected}`;
  const statLabel = STAT_TYPES[position].find((s) => s.key === statKey)?.label || "";

  const changePosition = (pos) => {
    setPosition(pos);
    setStatKey(STAT_TYPES[pos][0].key);
    setSelected(null);
    setSearch("");
  };

  return (
    <div style={{ background: C.bg, minHeight: "100vh", color: C.text, fontFamily: "'Inter', system-ui, sans-serif", padding: 20 }}>
      <div style={{ maxWidth: 1150, margin: "0 auto", display: "flex", flexDirection: "column", gap: 16 }}>
        <div>
          <div style={{ fontSize: 22, fontWeight: 800 }}>Prop Matchup Model</div>
          <div style={{ fontSize: 13, color: C.sub }}>Career average + head-to-head history + opponent matchup, validated against Week 1 results.</div>
        </div>

        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
          {POSITIONS.map((pos) => (
            <button key={pos} onClick={() => changePosition(pos)} style={{
              background: position === pos ? C.over : C.panel, color: position === pos ? "#1A1305" : C.text,
              border: `1px solid ${position === pos ? C.over : C.border}`, borderRadius: 7, padding: "7px 16px",
              fontWeight: 700, fontSize: 13, cursor: "pointer",
            }}>{pos}</button>
          ))}
          <div style={{ width: 1, height: 24, background: C.border, margin: "0 4px" }} />
          {STAT_TYPES[position].map((s) => (
            <button key={s.key} onClick={() => setStatKey(s.key)} style={{
              background: statKey === s.key ? C.panelAlt : "transparent", color: statKey === s.key ? C.text : C.sub,
              border: `1px solid ${statKey === s.key ? C.border : "transparent"}`, borderRadius: 7, padding: "6px 12px",
              fontWeight: 600, fontSize: 12.5, cursor: "pointer",
            }}>{s.label}</button>
          ))}
          <div style={{ marginLeft: "auto", position: "relative" }}>
            <Search size={14} style={{ position: "absolute", left: 9, top: 9, color: C.sub }} />
            <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search player"
              style={{ background: C.panel, border: `1px solid ${C.border}`, borderRadius: 7, padding: "7px 10px 7px 28px", color: C.text, fontSize: 13, width: 180 }} />
          </div>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "300px 1fr", gap: 16, alignItems: "start" }}>
          <div style={{ display: "flex", flexDirection: "column", gap: 6, maxHeight: 640, overflowY: "auto" }}>
            {filtered.map((p) => (
              <PlayerRow key={p.name} player={p} statKey={statKey} active={p.name === selected} onSelect={setSelected} line={lines[`${position}:${statKey}:${p.name}`]} />
            ))}
          </div>
          <div style={{ background: C.panel, border: `1px solid ${C.border}`, borderRadius: 10, padding: 20, minHeight: 500 }}>
            <DetailPanel player={activePlayer} statKey={statKey} statLabel={statLabel} line={lines[lineKey] || ""} setLine={(v) => setLines((prev) => ({ ...prev, [lineKey]: v }))} />
          </div>
        </div>
      </div>
    </div>
  );
}
